head.script:

	scwin.onpageload = function() {
        var jsonData = [{col1:"한글테스트가나다러", col2:"test1"}
                        ,{col1:"가나더라", col2:"aaa"}
                        ,{col1:"웹스퀘어1", col2:"abc"}
                        ,{col1:"웹스퀘어2", col2:"TEST2"}
                        ,{col1:"ABD", col2:"ABD"}];
        dataList1.setJSON(jsonData);
	};

	scwin.onpageunload = function() {

	};

    scwin.autoComplete1_oneditkeyup = function(info, e){
        var logStr = "oldValue=" + info.oldValue + ", newValue=" + info.newValue + ", keyCode=" + info.keyCode;
        WebSquare.logger.printLog(logStr);
        console.log("scwin.autoComplete1_oneditkeyup  : " + logStr);
    };

    scwin.autoComplete1_oneditenter = function(e) {
     var keyCode = (e.charCode) ? e.charCode : e.keyCode;   
     var logStr = "keyCode=" + keyCode;
	 window.val_enter = keyCode;
     WebSquare.logger.printLog(logStr);
     console.log("scwin.autoComplete1_oneditenter  : " + logStr);
 }

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate1 = function() {
		scwin.simulateWrapper('#autoComplete3_input', 'key-combo', {
			combo: 'ENTER'
		});
	}	
	scwin.checkVal = function() {
		return window.val_enter == 13;
	}	
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('autoComplete3_input').click()");
		WebSquare.wUnit.addCommand("pause", "400");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
